const {chromium}=require('playwright');const path=require('path');(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:412,height:860},deviceScaleFactor:2});await p.goto('file://'+path.resolve('t10.html')+'#demo');await p.waitForTimeout(400);await p.evaluate(()=>{S.tab='insights';render();});await p.waitForTimeout(1600);await p.evaluate(()=>document.querySelector('[data-w=top]')&&document.querySelector('[data-w=top]').scrollIntoView());await p.waitForTimeout(800);await p.screenshot({path:'/tmp/claude-0/-home-claude/860f62eb-517e-5d8f-84c5-65604e6e2975/scratchpad/z2.png'});await b.close();})();
